using System;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;
public static class V10GuiInspect{public static object Run(){var t=typeof(Editor).Assembly.GetType("UnityEditor.GameView");var view=EditorWindow.GetWindow(t);var f=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;return new{properties=t.GetProperties(f).Where(p=>p.Name.IndexOf("rect",StringComparison.OrdinalIgnoreCase)>=0||p.Name.IndexOf("target",StringComparison.OrdinalIgnoreCase)>=0||p.Name.IndexOf("size",StringComparison.OrdinalIgnoreCase)>=0).Select(p=>{try{return p.Name+"="+p.GetValue(view);}catch{return p.Name+"=<throw>";}}).ToArray(),fields=t.GetFields(f).Where(p=>p.Name.IndexOf("rect",StringComparison.OrdinalIgnoreCase)>=0||p.Name.IndexOf("target",StringComparison.OrdinalIgnoreCase)>=0||p.Name.IndexOf("size",StringComparison.OrdinalIgnoreCase)>=0).Select(p=>p.Name+"="+p.GetValue(view)).ToArray()};}}
